async function renamePresentation(page, title) {
  await page.getByRole('button', { name: 'Sunum adını değiştir' }).click()
  const input = page.getByRole('textbox', { name: 'Sunum adı' })
  await input.fill(title)
  await input.press('Enter')
  await page.waitForFunction((value) => document.querySelector('.topbar__title')?.textContent?.includes(value), title)
}
async function waitForServer(url, process, output) {
  const deadline = Date.now() + 30000
  while (Date.now() < deadline) {
    if (process.exitCode !== null) throw new Error(`Vite exited early: ${output()}`)
    try { const response = await fetch(url); if (response.ok) return } catch {}
    await new Promise((resolve) => setTimeout(resolve, 100))
  }
  throw new Error(`Vite did not become ready: ${output()}`)
}
async function waitForSlideOrder(page, expected) {
  const deadline = Date.now() + 6000
  while (Date.now() < deadline) {
    const actual = await page.locator('.filmstrip__entry').evaluateAll((items) => items.map((item) => item.dataset.slideId))
    if (actual.length === expected.length && actual.every((id, index) => id === expected[index])) return
    await page.waitForTimeout(50)
  }
  throw new Error(`Slide order did not settle to ${JSON.stringify(expected)}.`)
}
function freePort() { return new Promise((resolve, reject) => { const server = createServer(); server.once('error', reject); server.listen(0, '127.0.0.1', () => { const address = server.address(); if (!address || typeof address === 'string') return reject(new Error('No test port')); const { port } = address; server.close(() => resolve(port)) }) }) }
function assert(condition, message) { if (!condition) throw new Error(message) }
